const sd = $getWorkflowStaticData('global');
sd.seen = sd.seen || {};
const MAX_ATTEMPTS = 10, SETTLE_MS = 30 * 60 * 1000, BATCH = 10;
const now = Date.now();
const clean = (v, n = 200) => String(v ?? '').replace(/[\u0000-\u001f\u007f\u200b-\u200f\u202a-\u202e\u2066-\u2069]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, n);
const rows = $input.all().map(i => i.json || {});
const found = [];
const ids = new Set();
for (const r of rows) {
  const id = clean(r['Order ID'], 80);
  if (!id || id.length > 64 || ids.has(id)) continue;
  ids.add(id);
  found.push({ id, r });
}
if (!sd.baselined) {
  for (const { id } of found) sd.seen[id] = { s: 'baseline' };
  sd.baselined = new Date(now).toISOString();
  return [];
}
const out = [];
for (const { id, r } of found) {
  const e = sd.seen[id];
  if (e && e.s !== 'retry' && e.s !== 'incomplete') continue;
  if (e && e.s === 'retry' && (e.a || 0) >= MAX_ATTEMPTS) { e.s = 'gave_up'; continue; }
  const qty = clean(r['Quantity'], 10), total = clean(r['Total Price'], 20), gov = clean(r['Governorate'], 40);
  const complete = qty && total && gov;
  if (!complete) {
    if (!e) { sd.seen[id] = { s: 'incomplete', f: now }; continue; }
    if (e.s === 'incomplete' && now - (e.f || now) < SETTLE_MS) continue;
  }
  const dash = 'غير محدد';
  const text = ['🛒 طلب جديد – Dutti', `رقم الطلب: ${id}`, `الكمية: ${qty || dash}`, `الإجمالي: ${total ? total + ' ج.م' : dash}`,
    `المحافظة: ${gov || dash}`, 'الدفع: عند الاستلام', 'لوحة الطلبات: https://glowing-tabletop-fountain.lovable.app/admin'].join('\n');
  out.push({ json: { orderId: id, text } });
  if (out.length >= BATCH) break;
}
return out;

const sd = $getWorkflowStaticData('global'); sd.seen = sd.seen || {};
const id = $('Select new orders').item.json.orderId;
const mid = $json.result ? $json.result.message_id : $json.message_id;
sd.seen[id] = { s: 'sent', m: mid ?? null, t: new Date().toISOString() };
return { json: { orderId: id, status: 'sent', message_id: mid ?? null } };

const sd = $getWorkflowStaticData('global'); sd.seen = sd.seen || {};
const id = $('Select new orders').item.json.orderId;
const prev = sd.seen[id] || {};
const a = (prev.s === 'retry' ? (prev.a || 0) : 0) + 1;
sd.seen[id] = { s: 'retry', a, t: new Date().toISOString() };
return { json: { orderId: id, status: 'retry', attempts: a } };
